70:   private Pair(L left, R right) {
71:     this.left = left;
72:     this.right = right;
73:   }
74: 
75:   /**
76:    * Creates a new pair.
77:    *
78:    * @param left the left item
79:    * @param right the right item
80:    * @param <L> the type of the left item
81:    * @param <R> the type of the right item
82:    * @return a new pair
83:    */
84:   public static <L, R> Pair<L, R> of(L left, R right) {
85:     return new Pair<>(left, right);
86:   }
87: 
88:   /**
89:    * The left item of the pair.
90:    *
91:    * @return the left item of the pair
