104:   }
105: 
106:   /**
107:    * The left item of the pair.
108:    *
109:    * @return the left item of the pair
110:    */
111:   public L left() {
112:     return left;
113:   }
114: 
115:   /**
116:    * The right item of the pair.
117:    *
118:    * @return the right item of the pair
