201:   }
202: 
203:   /**
204:    * Creates a new pair, with the left item being the result of applying the given function to the left item of {@code this}.
205:    * <p>
206:    * The right value is unchanged.
207:    *
208:    * @param function a transformer for the left value
209:    * @param <T> the type of the new left value
210:    * @return a new pair, with the left item being the result of applying the given function to the left item of {@code this}
211:    * @throws Exception any thrown by {@code function}
212:    */
213:   public <T> Pair<T, R> mapLeft(Function<? super L, ? extends T> function) throws Exception {
214:     T t = function.apply(left);
215:     return of(t, right);
216:   }
217: 
218:   /**
219:    * Creates a new pair, with the right item being the result of applying the given function to the right item of {@code this}.
220:    * <p>
221:    * The left value is unchanged.
222:    *
223:    * @param function a transformer for the right value
224:    * @param <T> the type of the new right value
225:    * @return a new pair, with the right item being the result of applying the given function to the right item of {@code this}
226:    * @throws Exception any thrown by {@code function}
227:    */
228:   public <T> Pair<L, T> mapRight(Function<? super R, ? extends T> function) throws Exception {
229:     T t = function.apply(right);
230:     return of(left, t);
231:   }
232: 
233:   /**
234:    * Applies the given function to {@code this}, returning the result.
235:    *
236:    * @param function a function to apply to {@code this}
237:    * @param <T> the function result type
