255:   }
256: 
257:   /**
258:    * Convenience function for returning the right item of a pair.
259:    *
260:    * @param <R> the type of the right item
261:    * @param <P> the pair type
262:    * @return a function that when applied to a pair returns the right item
263:    */
264:   public static <R, P extends Pair<?, R>> Function<P, R> unpackRight() {
