1126:   /**
1127:    * Transforms the promised value by applying the given function to it that returns a promise for the transformed value, if it satisfies the predicate.
1128:    *
1129:    * <pre class="java">{@code
1130:    * import ratpack.test.exec.ExecHarness;
1131:    * import ratpack.exec.ExecResult;
1132:    * import ratpack.exec.Promise;
1133:    *
1134:    * import static org.junit.Assert.assertEquals;
1135:    *
1136:    * public class Example {
1137:    *   public static void main(String... args) throws Exception {
1138:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
1139:    *         Promise.value("foo")
1140:    *           .flatMapIf(s -> s.contains("f"), s -> Promise.value(s.toUpperCase()))
1141:    *           .flatMapIf(s -> s.contains("f"), s -> Promise.value(s + "-BAR"))
1142:    *     );
1143:    *
1144:    *     assertEquals("FOO", result.getValue());
1145:    *   }
1146:    * }
1147:    * }</pre>
1148:    *
1149:    * @param predicate the condition to satisfy in order to be transformed
1150:    * @param transformer the transformation to apply to the promised value
1151:    * @return a promise
1152:    * @since 1.4
1153:    */
1154:   default Promise<T> flatMapIf(Predicate<? super T> predicate, Function<? super T, ? extends Promise<T>> transformer) {
1155:     return flatMap(t -> predicate.apply(t) ? transformer.apply(t) : Promise.value(t));
1156:   }
