1564:    *         Promise.<String>sync(() -> {
1565:    *           events.add("promise");
1566:    *           return "foo";
1567:    *         })
1568:    *           .wiretap(r -> events.add("wiretap: " + r.getValue()))
1569:    *           .then(v -> events.add("then"))
1570:    *     );
1571:    *
1572:    *     assertEquals(Arrays.asList("promise", "wiretap: foo", "then"), events);
1573:    *   }
1574:    * }
1575:    * }</pre>
1576:    *
1577:    * @param listener the result listener
1578:    * @return effectively, {@code this} promise
1579:    */
1580:   default Promise<T> wiretap(Action<? super Result<T>> listener) {
1581:     return transform(up -> down ->
1582:       up.connect(new Downstream<T>() {
1583:         @Override
1584:         public void success(T value) {
