518:    * import ratpack.test.UnitTest;
519:    * import ratpack.test.handling.HandlingResult;
520:    * import ratpack.test.handling.RequestFixture;
521:    *
522:    * public class Example {
523:    *   public static class ForkingHandler implements Handler {
524:    *     public void handle(final Context context) {
525:    *       final int numJobs = 3;
526:    *       final Integer failOnIteration = context.getPathTokens().asInt("failOn");
527:    *
528:    *       context.promise(new Action&lt;Fulfiller&lt;Integer&gt;&gt;() {
529:    *         private final AtomicInteger counter = new AtomicInteger();
530:    *         private final AtomicReference&lt;Throwable&gt; error = new AtomicReference&lt;&gt;();
531:    *
532:    *         public void execute(final Fulfiller&lt;Integer&gt; fulfiller) {
533:    *           for (int i = 0; i < numJobs; ++i) {
534:    *             final int iteration = i;
535:    *
536:    *             context.fork(new Action&lt;Execution&gt;() {
537:    *               public void execute(Execution execution) throws Exception {
538:    *
539:    *                 // Important to set a error handler that somehow signals completion so the request processing can continue
540:    *                 // (the error handler is invoked if an exception is uncaught during the execution)
541:    *                 execution.setErrorHandler(new Action&lt;Throwable&gt;() {
542:    *                   public void execute(Throwable throwable) {
543:    *                     error.compareAndSet(null, throwable); // just take the first error
544:    *                     completeJob();
545:    *                   }
546:    *                 });
547:    *
548:    *                 if (failOnIteration != null && failOnIteration.intValue() == iteration) {
549:    *                   throw new Exception("bang!");
550:    *                 } else {
551:    *                   completeJob();
552:    *                 }
553:    *               }
554:    *
555:    *               private void completeJob() {
556:    *                 if (counter.incrementAndGet() == numJobs) {
557:    *                   Throwable throwable = error.get();
558:    *                   if (throwable == null) {
559:    *                     fulfiller.success(numJobs);
560:    *                   } else {
561:    *                     fulfiller.error(throwable);
562:    *                   }
563:    *                 }
564:    *               }
565:    *             });
566:    *           }
567:    *         }
568:    *       }).then(new Action&lt;Integer&gt;() {
569:    *         public void execute(Integer integer) {
570:    *           context.render(integer.toString());
571:    *         }
572:    *       });
573:    *     }
574:    *   }
575:    *
576:    *   public static void main(String[] args) {
577:    *     HandlingResult result = UnitTest.handle(new ForkingHandler(), Actions.noop());
578:    *     assert result.rendered(String.class).equals("3");
579:    *
580:    *     result = UnitTest.handle(new ForkingHandler(), new Action&lt;RequestFixture&gt;() {
581:    *       public void execute(RequestFixture fixture) {
582:    *         fixture.pathBinding(Collections.singletonMap("failOn", "2"));
583:    *       }
584:    *     });
585:    *
586:    *     assert result.getException().getMessage().equals("bang!");
587:    *   }
588:    * }
